import pathlib, shutil, subprocess, sys

WS = pathlib.Path('/workspace')
ORIG = pathlib.Path('/tmp/orig-payment')
OUT = pathlib.Path('/tmp/mutants')

def fresh(name):
    d = OUT / name
    if d.exists(): shutil.rmtree(d)
    (d / 'src').mkdir(parents=True)
    (d / 'checks').mkdir()
    for f in (WS / 'src').glob('*.ts'): shutil.copy(f, d / 'src' / f.name)
    shutil.copy(WS / 'checks' / 'public.cjs', d / 'checks' / 'public.cjs')
    shutil.copy(WS / 'tsconfig.json', d / 'tsconfig.json')
    return d

def sub(d, rel, old, new):
    p = d / rel
    s = p.read_text()
    n = s.count(old)
    assert n == 1, f'{d.name}: expected 1 match in {rel}, got {n}: {old!r}'
    p.write_text(s.replace(old, new))

LEDGER_RACE = '''export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  readonly #receiptsByKey = new Map<string, Map<string, Receipt>>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    let keys = this.#receiptsByKey.get(tenant);
    const original = keys?.get(key);
    await new Promise(r => setTimeout(r, 1));
    if (original !== undefined) {
      if (original.cents !== cents) throw new Error('key conflict');
      return original;
    }
    const receipt: Receipt = { id: this.entries.length + 1, tenant, key, cents };
    if (keys === undefined) { keys = new Map<string, Receipt>(); this.#receiptsByKey.set(tenant, keys); }
    keys.set(key, receipt);
    this.entries.push(receipt);
    return receipt;
  }
}
'''

