const assert = require('node:assert/strict');
const { Ledger } = require('/workspace/.build/ledger');
const { PaymentService } = require('/workspace/.build/service');
const { Transient } = require('/workspace/.build/transport');

const rnd = n => Math.floor(Math.random() * n);
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function round() {
  const ledger = new Ledger();
  const ops = [];
  for (let i = 0; i < 40; i++) {
    const invalid = rnd(10) === 0;
    const tenant = ['a', 'b'][rnd(2)];
    const key = ['k1', 'k2', 'k3'][rnd(3)];
    const cents = [1, 2, 3][rnd(3)];
    const attempts = invalid ? [0, 6][rnd(2)] : 1 + rnd(5);
    // per-try script: 'ok' | 'transient' (ack lost) | 'other' (non-retryable)
    const plan = Array.from({ length: 7 }, () => { const x = Math.random(); return x < 0.4 ? 'transient' : x < 0.45 ? 'other' : 'ok'; });
    const op = { tenant, key, cents, attempts, invalid, acks: [], thrown: [], calls: 0 };
    op.service = new PaymentService(ledger, { acknowledge: async receipt => {
      op.acks.push(receipt);
      const action = plan[op.calls++];
      await sleep(rnd(3));
      if (action === 'transient') { const e = new Transient('lost ' + op.calls); op.thrown.push(e); throw e; }
      if (action === 'other') { const e = new TypeError('hard ' + op.calls); op.thrown.push(e); throw e; }
    }});
    op.plan = plan;
    ops.push(op);
  }
  const settled = await Promise.allSettled(ops.map(async op => { await sleep(rnd(4)); return op.service.pay(op.tenant, op.key, op.cents, op.attempts); }));

  for (let i = 0; i < ops.length; i++) {
    const op = ops[i], s = settled[i];
    if (op.invalid) {
      assert.equal(s.status, 'rejected'); assert.equal(s.reason.message, 'invalid payment');
      assert.equal(op.acks.length, 0); continue;
    }
    const entry = ledger.entries.find(e => e.tenant === op.tenant && e.key === op.key);
    if (s.status === 'fulfilled') {
      const r = s.value;
      assert.equal(r.tenant, op.tenant); assert.equal(r.key, op.key); assert.equal(r.cents, op.cents);
      assert.equal(r, entry, 'receipt must be the single committed debit for its tenant/key');
      assert.equal(op.acks.length, op.calls); assert.ok(op.calls <= op.attempts);
      for (const a of op.acks) assert.equal(a, r, 'every ack must forward the same receipt');
      assert.equal(op.plan[op.calls - 1], 'ok');
    } else if (s.reason instanceof Transient) {
      assert.equal(op.calls, op.attempts, 'exhausted => exactly attempts tries');
      assert.equal(s.reason, op.thrown[op.thrown.length - 1], 'last Transient preserved');
      assert.ok(op.thrown.every(e => e instanceof Transient));
